// Quaternion Julia - color only, ANIMATED. Runs INSIDE shadeSurface().
// The 3D cousin of the Julia set: every point of the surface is a quaternion
// q = (x, y, z, 0) iterated as q -> q^2 + c. The surface CUTS the 4D fractal, so what
// you see is the cross-section of the set by your object: a sphere shows one
// slice, a torus another. c drifts slowly with time and the slice morphs.
// Colors: smooth escape count (bands) + an orbit trap (glow along the filaments).
// No displacement: costs one evaluation per pixel, cheap at any resolution.
// In scope: pModel, n_model, t. Dock colors: u_col1 = light bands, u_col2 = deep tone.

float ZOOM  = 0.9 * max(E, 0.05);    // slider E   // size of the slice   [0.5 .. 2]
float MORPH = 0.25 * F;              // slider F   // morph speed         [0 .. 1]
const int ITER = 24;                 // detail of the boundary             [12 .. 48]

// c wanders on a small loop around a classic "dendrite" value
vec4 cq = vec4(-0.291, -0.399, 0.339, 0.437)
        + 0.10 * vec4(sin(MORPH * t), cos(0.73 * MORPH * t), sin(0.51 * MORPH * t + 1.0), 0.0);

vec4 q = vec4(pModel * ZOOM, 0.0);
float trap = 1e9;
float r2 = 0.0;
float n = float(ITER);
for (int i = 0; i < ITER; i++) {
    // quaternion square: (a, v)^2 = (a^2 - v.v, 2 a v)
    q = vec4(q.x * q.x - dot(q.yzw, q.yzw), 2.0 * q.x * q.yzw) + cq;
    r2 = dot(q, q);
    trap = min(trap, abs(q.y) + 0.5 * abs(q.z));
    if (r2 > 64.0) { n = float(i); break; }
}

vec3 col;
if (r2 <= 64.0) {
    // inside the set: deep tone, lit by the orbit trap along the filaments
    col = mix(ubuf.u_col2 * 0.6, ubuf.u_col2 * 2.2 + 0.15 * ubuf.u_col1, exp(-4.0 * trap));
} else {
    // smooth escape count -> continuous bands instead of rings
    float sn = n + 1.0 - log2(log2(r2) * 0.5);
    float k  = clamp(sn / float(ITER), 0.0, 1.0);     // 0 far out .. 1 at the boundary
    float band = 0.5 + 0.5 * cos(1.1 * sn - 0.6 * MORPH * t);
    vec3 pal = 0.5 + 0.5 * cos(6.2832 * (0.06 * sn + vec3(0.0, 0.12, 0.30)));
    col = mix(ubuf.u_col2, ubuf.u_col1, smoothstep(0.0, 0.6, k));
    col *= 0.7 + 0.3 * band;
    col = mix(col, pal * ubuf.u_col1, 0.3 * k);
}

textureCol = col;
